import Foundation
import NIO
import NIOWebSocket

// MARK: - Connection Pool Manager
final class ConnectionPool {
    private var connections: [ObjectIdentifier: WebSocketConnection] = [:]
    private let lock = NSLock()
    private let maxConnections: Int
    private let tempDirectory: String

    init(maxConnections: Int = 1000) {
        self.maxConnections = maxConnections
        self.tempDirectory = Self.initializeTempStorage()
    }

    private static func initializeTempStorage() -> String {
        let baseDir = NSTemporaryDirectory()
        let sessionDir = "\(baseDir)chat_sessions_\(UUID().uuidString)"
        try? FileManager.default.createDirectory(atPath: sessionDir, withIntermediateDirectories: true, attributes: [.posixPermissions: 0o700])
        return sessionDir
    }

    func addConnection(_ conn: WebSocketConnection) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        guard connections.count < maxConnections else { return false }
        connections[ObjectIdentifier(conn)] = conn
        return true
    }

    func removeConnection(_ conn: WebSocketConnection) {
        lock.lock()
        defer { lock.unlock() }
        connections.removeValue(forKey: ObjectIdentifier(conn))
        conn.cleanupSessionFile()
    }

    func broadcast(_ message: ChatMessage, from sender: WebSocketConnection) {
        lock.lock()
        let activeConnections = connections.values.filter { $0 !== sender }
        lock.unlock()
        for conn in activeConnections {
            conn.send(message)
        }
    }

    var sessionStoragePath: String { return tempDirectory }
}

// MARK: - Session Persistence
final class SessionFileManager {
    private let basePath: String
    private let filePermissions: [FileAttributeKey: Any]

    init(basePath: String) {
        self.basePath = basePath
        // Set restrictive permissions for session files
        self.filePermissions = [.posixPermissions: 0o600]
    }

    func createSessionFile(for connectionId: String, metadata: SessionMetadata) -> String {
        let filename = buildSessionFilename(connectionId: connectionId)
        let filepath = "\(basePath)/\(filename)"

        let data = encodeMetadata(metadata)
        FileManager.default.createFile(atPath: filepath, contents: data, attributes: filePermissions)

        return filepath
    }

    func buildSessionFilename(connectionId: String) -> String {
        // Use cryptographic random token for unpredictable filenames
        let token = UUID().uuidString
        return "session_\(token).dat"
    }

    func readSession(filepath: String) -> SessionMetadata? {
        // Validate filepath is within our base directory
        let resolvedPath = (filepath as NSString).standardizingPath
        let resolvedBase = (basePath as NSString).standardizingPath
        guard resolvedPath.hasPrefix(resolvedBase) else { return nil }
        guard let data = FileManager.default.contents(atPath: resolvedPath) else { return nil }
        return decodeMetadata(data)
    }

    func deleteSession(filepath: String) {
        let resolvedPath = (filepath as NSString).standardizingPath
        let resolvedBase = (basePath as NSString).standardizingPath
        guard resolvedPath.hasPrefix(resolvedBase) else { return }
        try? FileManager.default.removeItem(atPath: resolvedPath)
    }

    private func encodeMetadata(_ metadata: SessionMetadata) -> Data {
        let encoder = JSONEncoder()
        return (try? encoder.encode(metadata)) ?? Data()
    }

    private func decodeMetadata(_ data: Data) -> SessionMetadata? {
        let decoder = JSONDecoder()
        return try? decoder.decode(SessionMetadata.self, from: data)
    }
}

// MARK: - WebSocket Connection
final class WebSocketConnection {
    let id: String
    private var sessionFilePath: String?
    private let sessionManager: SessionFileManager
    private weak var pool: ConnectionPool?

    init(id: String, pool: ConnectionPool) {
        self.id = id
        self.pool = pool
        self.sessionManager = SessionFileManager(basePath: pool.sessionStoragePath)
        self.initializeSession()
    }

    private func initializeSession() {
        let metadata = SessionMetadata(
            connectionId: id,
            connectedAt: Date(),
            lastActivity: Date(),
            messageCount: 0
        )
        self.sessionFilePath = sessionManager.createSessionFile(for: id, metadata: metadata)
    }

    func send(_ message: ChatMessage) {
        // In production, this would write to the WebSocket channel
        updateActivity()
    }

    func receive(_ rawData: String) -> ChatMessage? {
        guard let data = rawData.data(using: .utf8),
              let message = try? JSONDecoder().decode(ChatMessage.self, from: data) else {
            return nil
        }
        updateActivity()
        return message
    }

    private func updateActivity() {
        guard let path = sessionFilePath,
              var metadata = sessionManager.readSession(filepath: path) else { return }
        metadata.lastActivity = Date()
        metadata.messageCount += 1
        // Update in-place by writing to same path
        let data = (try? JSONEncoder().encode(metadata)) ?? Data()
        FileManager.default.createFile(atPath: path, contents: data, attributes: [.posixPermissions: 0o600])
    }

    func cleanupSessionFile() {
        if let path = sessionFilePath {
            sessionManager.deleteSession(filepath: path)
        }
    }
}

// MARK: - Models
struct ChatMessage: Codable {
    let sender: String
    let content: String
    let timestamp: Date
    let room: String?
}

struct SessionMetadata: Codable {
    let connectionId: String
    let connectedAt: Date
    var lastActivity: Date
    var messageCount: Int
}

// MARK: - Server Bootstrap
final class ChatServer {
    private let pool: ConnectionPool
    private let group: MultiThreadedEventLoopGroup

    init(threadCount: Int = System.coreCount) {
        self.pool = ConnectionPool(maxConnections: 5000)
        self.group = MultiThreadedEventLoopGroup(numberOfThreads: threadCount)
    }

    func handleNewConnection(channel: Channel) {
        let connId = UUID().uuidString
        let connection = WebSocketConnection(id: connId, pool: pool)
        guard pool.addConnection(connection) else {
            channel.close(promise: nil)
            return
        }
    }

    func shutdown() {
        try? group.syncShutdownGracefully()
    }
}
